from base.service import BaseServicefrom helpers.search import Paginationfrom models.container import Containerfrom repositories.container import ContainerRepositoryfrom schemas.container import FullContainerShowfrom sqlalchemy.ext.asyncio import AsyncSessionclass ContainerService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)    async def get_full_containers(            self, pagination: Pagination,    ) -> list[FullContainerShow]:        result = await self.repository.get_containers_with_content_counts(**pagination.dict())        return [            FullContainerShow(                container=container,                post_count=post_count,                comment_count=comment_count            )            for container, post_count, comment_count in result        ]    async def get_full_container(self, container: Container) -> FullContainerShow:        container, post_count, comment_count = \            await self.repository.get_containers_with_content_counts(container_id=container.id)        return FullContainerShow(container=container, post_count=post_count, comment_count=comment_count)